properties.query:
let Tykit=externaldata(Domain:string)
[h'https://raw.githubusercontent.com/SlimKQL/Hunting-Queries-Detection-Rules/refs/heads/main/IOC/TyKit.csv']
with (format='csv', ignoreFirstRecord=true);
let svg =
DeviceFileEvents
| where ActionType == @"FileCreated"
| where FileName endswith ".svg"
|project SVGTime=Timestamp,DeviceId,InitiatingProcessAccountName,DeviceName,ActionType,FileName,SHA256,InitiatingProcessFileName; 
let ioc =
DeviceNetworkEvents 
| where RemoteUrl has "segy" or RemoteUrl has_any (Tykit) or RemoteUrl matches regex "^loginmicr(o|0)sft.*?\\.([a-z0-9]+)?[a-zA-Z0-9]+\\.cc$"
| project IOCTime=Timestamp,DeviceId,InitiatingProcessAccountName,DeviceName,ActionType,RemoteUrl;
svg
| join kind=inner (
    ioc
) on DeviceId
| project DeviceId,InitiatingProcessAccountName,DeviceName,RemoteUrl
